var AgentApiError = class extends Error {
	status;
	code;
	constructor(message, status, code = "agent_error") {
		super(message);
		this.name = "AgentApiError";
		this.status = status;
		this.code = code;
	}
};
async function postAgentJson(endpoint, payload, signal) {
	const res = await fetch(endpoint, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify(payload),
		signal
	});
	const data = await res.json().catch(() => ({}));
	if (!res.ok) throw new AgentApiError(data?.error?.message || `AI service unavailable (HTTP ${res.status}). Ensure GEMINI_API_KEY is configured on the server.`, res.status, data?.error?.code || "agent_error");
	return data;
}
function askUserCopilot(request, signal) {
	return postAgentJson(AGENT_ENDPOINTS.userCopilot, request, signal);
}
function runSiteManagerAgent(request, signal) {
	return postAgentJson(AGENT_ENDPOINTS.siteManager, request, signal);
}
function runCommunityAssist(request, signal) {
	return postAgentJson(AGENT_ENDPOINTS.communityAssist, request, signal);
}
async function streamChatGptAgent(request, handlers, signal) {
	const res = await fetch(AGENT_ENDPOINTS.chatgptStream, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify(request),
		signal
	});
	if (!res.ok) {
		const errBody = await res.json().catch(() => ({}));
		throw new AgentApiError(errBody?.error?.message || `AI service unavailable (HTTP ${res.status}). Ensure GEMINI_API_KEY is configured on the server.`, res.status, errBody?.error?.code || "agent_error");
	}
	if (!res.body) throw new AgentApiError("Empty response stream from server.", 502, "empty_stream");
	const reader = res.body.getReader();
	const decoder = new TextDecoder();
	let buffer = "";
	const dispatchFrame = (frame) => {
		const lines = frame.split(/\r?\n/);
		const dataLines = [];
		for (const line of lines) if (line.startsWith("data:")) dataLines.push(line.slice(5).trimStart());
		if (dataLines.length === 0) return;
		const rawJson = dataLines.join("\n");
		try {
			const parsed = JSON.parse(rawJson);
			handlers.onEvent(parsed);
		} catch {}
	};
	while (true) {
		const { done, value } = await reader.read();
		if (done) break;
		buffer += decoder.decode(value, { stream: true });
		let boundary = buffer.indexOf("\n\n");
		while (boundary !== -1) {
			const frame = buffer.slice(0, boundary);
			buffer = buffer.slice(boundary + 2);
			dispatchFrame(frame);
			boundary = buffer.indexOf("\n\n");
		}
	}
	if (buffer.trim()) dispatchFrame(buffer);
}
